'use client';

import { useMemo, useState } from "react";

const materialDatabase = [
  { name: "Cement", category: "Structural", unit: "Bag", rates: { default: 500, Kolkata: 500, Delhi: 520, Mumbai: 540, Bengaluru: 530 } },
  { name: "Sand", category: "Structural", unit: "CFT", rates: { default: 65, Kolkata: 65, Delhi: 70, Mumbai: 75, Bengaluru: 72 } },
  { name: "Bricks", category: "Masonry", unit: "Pcs", rates: { default: 9, Kolkata: 9, Delhi: 10, Mumbai: 11, Bengaluru: 10 } },
  { name: "Steel", category: "Structural", unit: "Kg", rates: { default: 68, Kolkata: 68, Delhi: 70, Mumbai: 72, Bengaluru: 69 } },
  { name: "Stone / Aggregate", category: "Structural", unit: "CFT", rates: { default: 70, Kolkata: 70, Delhi: 75, Mumbai: 80, Bengaluru: 74 } },
  { name: "Concrete", category: "Structural", unit: "Cu m", rates: { default: 6500, Kolkata: 6500, Delhi: 6800, Mumbai: 7200, Bengaluru: 6900 } },
  { name: "Tiles", category: "Finishing", unit: "Sq ft", rates: { default: 80, Kolkata: 80, Delhi: 85, Mumbai: 95, Bengaluru: 90 } },
  { name: "Paint", category: "Finishing", unit: "Litre", rates: { default: 220, Kolkata: 220, Delhi: 230, Mumbai: 245, Bengaluru: 235 } },
  { name: "PVC Pipe", category: "Plumbing", unit: "Unit", rates: { default: 180, Kolkata: 180, Delhi: 190, Mumbai: 200, Bengaluru: 195 } },
  { name: "Electrical Wire", category: "Electrical", unit: "Unit", rates: { default: 120, Kolkata: 120, Delhi: 125, Mumbai: 135, Bengaluru: 130 } },
];

const defaultMaterials = materialDatabase.slice(0, 4).map((m) => ({
  name: m.name, qty: 0, unit: m.unit, rate: m.rates.default, category: m.category, rateSource: "Suggested"
}));

const units = ["Bag", "CFT", "Cu m", "Pcs", "Kg", "Ton", "Sq ft", "Sq m", "Litre", "Unit"];
const locations = ["", "Kolkata", "Delhi", "Mumbai", "Bengaluru"];

const money = (value, currency) =>
  new Intl.NumberFormat("en-IN", {
    style: "currency",
    currency,
    maximumFractionDigits: 2,
  }).format(Number(value) || 0);

export default function Calculator() {
  const [project, setProject] = useState({
    name: "My Construction Project",
    location: "",
    currency: "INR",
    area: 1000,
    areaUnit: "sq ft",
    rate: 1800,
    mode: "area",
    labour: 10,
    transport: 0,
    other: 3,
    tax: 0,
    contingency: 2,
    wastage: 0,
  });

  const [materials, setMaterials] = useState(defaultMaterials);
  const [saved, setSaved] = useState(false);
  const [materialSearch, setMaterialSearch] = useState("");

  const materialSubtotal = useMemo(
    () =>
      materials.reduce(
        (sum, m) => sum + (Number(m.qty) || 0) * (Number(m.rate) || 0),
        0
      ),
    [materials]
  );

  const areaBase =
    (Number(project.area) || 0) * (Number(project.rate) || 0);

  // In Detailed BOQ mode the material subtotal is the base.
  // Wastage is calculated separately so it is never double-counted.
  const baseCost = project.mode === "area" ? areaBase : materialSubtotal;
  const wastage =
    project.mode === "boq"
      ? materialSubtotal * ((Number(project.wastage) || 0) / 100)
      : 0;
  const costBeforeAddons = baseCost + wastage;

  const labourCost =
    costBeforeAddons * ((Number(project.labour) || 0) / 100);
  const transportCost = Number(project.transport) || 0;
  const otherCost =
    costBeforeAddons * ((Number(project.other) || 0) / 100);
  const contingency =
    costBeforeAddons * ((Number(project.contingency) || 0) / 100);

  const taxable =
    costBeforeAddons +
    labourCost +
    transportCost +
    otherCost +
    contingency;

  const tax = taxable * ((Number(project.tax) || 0) / 100);
  const grandTotal = taxable + tax;

  const updateProject = (key, value) =>
    setProject((p) => ({ ...p, [key]: value }));

  const updateMaterial = (index, key, value) => {
    setMaterials((list) =>
      list.map((m, i) => (i === index ? { ...m, [key]: value } : m))
    );
  };

  const getSuggestedRate = (materialName) => {
    const item = materialDatabase.find((m) => m.name === materialName);
    if (!item || project.currency !== "INR") return 0;
    return item.rates[project.location] ?? item.rates.default;
  };

  const selectMaterial = (index, materialName) => {
    const item = materialDatabase.find((m) => m.name === materialName);
    if (!item) return;
    const suggestedRate = getSuggestedRate(materialName);
    setMaterials((list) => list.map((m, i) => i === index ? {
      ...m, name: item.name, unit: item.unit, category: item.category, rate: suggestedRate, rateSource: "Suggested"
    } : m));
  };

  const updateLocation = (value) => {
    updateProject("location", value);
    if (project.currency !== "INR") return;
    setMaterials((list) => list.map((m) => {
      const item = materialDatabase.find((db) => db.name === m.name);
      if (!item || m.rateSource !== "Suggested") return m;
      return { ...m, rate: item.rates[value] ?? item.rates.default };
    }));
  };

  const addMaterial = () =>
    setMaterials((list) => [
      ...list,
      { name: "", qty: 0, unit: "Unit", rate: 0, category: "Custom", rateSource: "Manual" },
    ]);

  const removeMaterial = (index) =>
    setMaterials((list) => list.filter((_, i) => i !== index));

  const saveEstimate = () => {
    localStorage.setItem(
      "buildnaro-estimate",
      JSON.stringify({
        project,
        materials,
        materialSubtotal,
        grandTotal,
        savedAt: new Date().toISOString(),
      })
    );
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  const printEstimate = () => window.print();

  return (
    <main>
      <header className="topbar">
        <a className="brand" href="/">
          Build<span>Naro</span>
        </a>
        <a href="/">Home</a>
      </header>

      <section className="hero">
        <div className="eyebrow">BUILDNARO CONSTRUCTION TOOLS</div>
        <h1>Construction Estimate Calculator</h1>
        <p>
          Create a clear construction cost estimate with materials, labour,
          transport, tax, wastage and contingency.
        </p>
      </section>

      <section className="wrap">
        <div className="grid">
          <div className="card">
            <h2>Project Details</h2>
            <div className="form-grid">
              <label>
                Project Name
                <input
                  value={project.name}
                  onChange={(e) => updateProject("name", e.target.value)}
                />
              </label>

              <label>
                Location / Rate Market
                <select value={project.location} onChange={(e) => updateLocation(e.target.value)}>
                  <option value="">Default / Other</option>
                  {locations.filter(Boolean).map((location) => <option key={location}>{location}</option>)}
                </select>
                <small className="field-note">Starter rates are editable estimates, not live market quotes.</small>
              </label>

              <label>
                Currency
                <select
                  value={project.currency}
                  onChange={(e) =>
                    updateProject("currency", e.target.value)
                  }
                >
                  <option>INR</option>
                  <option>USD</option>
                  <option>BDT</option>
                  <option>AED</option>
                  <option>GBP</option>
                </select>
              </label>

              <label>
                Calculation Mode
                <select
                  value={project.mode}
                  onChange={(e) => updateProject("mode", e.target.value)}
                >
                  <option value="area">Area × Rate</option>
                  <option value="boq">Detailed BOQ</option>
                </select>
              </label>

              {project.mode === "area" && (
                <>
                  <label>
                    Built-up Area
                    <input
                      type="number"
                      min="0"
                      value={project.area}
                      onChange={(e) =>
                        updateProject("area", e.target.value)
                      }
                    />
                  </label>

                  <label>
                    Area Unit
                    <select
                      value={project.areaUnit}
                      onChange={(e) =>
                        updateProject("areaUnit", e.target.value)
                      }
                    >
                      <option>sq ft</option>
                      <option>sq m</option>
                      <option>sq yd</option>
                    </select>
                  </label>

                  <label>
                    Construction Rate / Area
                    <input
                      type="number"
                      min="0"
                      value={project.rate}
                      onChange={(e) =>
                        updateProject("rate", e.target.value)
                      }
                    />
                  </label>
                </>
              )}
            </div>
          </div>

          <div className="card summary">
            <h2>Estimate Summary</h2>
            <div className="summary-main">
              {money(grandTotal, project.currency)}
            </div>
            <p>Estimated Grand Total</p>

            {project.mode === "area" && (
              <>
                <div className="mini">
                  Rate: {money(project.rate, project.currency)} /{" "}
                  {project.areaUnit}
                </div>
                <div className="mini">
                  Area: {Number(project.area || 0).toLocaleString()}{" "}
                  {project.areaUnit}
                </div>
              </>
            )}

            {project.mode === "boq" && (
              <div className="mini">
                Materials: {money(materialSubtotal, project.currency)}
              </div>
            )}
          </div>
        </div>

        <div className="card">
          <div className="section-head">
            <div>
              <h2>Materials / BOQ</h2>
              <p>Add quantity and rate for each material.</p>
            </div>
            <button onClick={addMaterial}>+ Add Material</button>
          </div>

          <div className="material-tools">
            <input
              className="material-search"
              value={materialSearch}
              onChange={(e) => setMaterialSearch(e.target.value)}
              placeholder="Search materials by name or category..."
            />
            <span>{materialDatabase.length} starter materials</span>
          </div>

          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Material Name</th>
                  <th>Quantity</th>
                  <th>Unit</th>
                  <th>Rate</th>
                  <th>Amount</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {materials.map((m, i) => {
                  const amount =
                    (Number(m.qty) || 0) * (Number(m.rate) || 0);

                  return (
                    <tr key={i}>
                      <td>
                        <select
                          value={materialDatabase.some((db) => db.name === m.name) ? m.name : "__custom__"}
                          onChange={(e) => {
                            if (e.target.value === "__custom__") {
                              updateMaterial(i, "name", "");
                              updateMaterial(i, "category", "Custom");
                              updateMaterial(i, "rateSource", "Manual");
                              return;
                            }
                            selectMaterial(i, e.target.value);
                          }}
                        >
                          <option value="__custom__">Custom material</option>
                          {materialDatabase
                            .filter((db) => !materialSearch || db.name.toLowerCase().includes(materialSearch.toLowerCase()) || db.category.toLowerCase().includes(materialSearch.toLowerCase()))
                            .map((db) => <option key={db.name} value={db.name}>{db.name} — {db.category}</option>)}
                        </select>
                        {!materialDatabase.some((db) => db.name === m.name) && (
                          <input
                            value={m.name}
                            placeholder="Custom material name"
                            onChange={(e) => updateMaterial(i, "name", e.target.value)}
                          />
                        )}
                      </td>
                      <td>
                        <input
                          type="number"
                          min="0"
                          step="any"
                          value={m.qty}
                          onChange={(e) =>
                            updateMaterial(i, "qty", e.target.value)
                          }
                        />
                      </td>
                      <td>
                        <select
                          value={m.unit}
                          onChange={(e) =>
                            updateMaterial(i, "unit", e.target.value)
                          }
                        >
                          {units.map((unit) => (
                            <option key={unit}>{unit}</option>
                          ))}
                        </select>
                      </td>
                      <td>
                        <input
                          type="number"
                          min="0"
                          step="any"
                          value={m.rate}
                          onChange={(e) => {
                            updateMaterial(i, "rate", e.target.value);
                            updateMaterial(i, "rateSource", "Manual");
                          }}
                        />
                        <small className="rate-source">{m.rateSource || "Manual"}</small>
                      </td>
                      <td className="amount">
                        {money(amount, project.currency)}
                      </td>
                      <td>
                        <button
                          className="delete"
                          aria-label={`Remove ${m.name || "material"}`}
                          onClick={() => removeMaterial(i)}
                        >
                          ×
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
              <tfoot>
                <tr>
                  <td colSpan="4" className="boq-total-label">
                    Material Subtotal
                  </td>
                  <td className="amount">
                    {money(materialSubtotal, project.currency)}
                  </td>
                  <td></td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>

        <div className="grid">
          <div className="card">
            <h2>Additional Costs</h2>
            <div className="form-grid">
              <label>
                Material Wastage %
                <input
                  type="number"
                  min="0"
                  step="any"
                  value={project.wastage}
                  onChange={(e) =>
                    updateProject("wastage", e.target.value)
                  }
                  disabled={project.mode !== "boq"}
                />
              </label>

              <label>
                Labour %
                <input
                  type="number"
                  min="0"
                  step="any"
                  value={project.labour}
                  onChange={(e) =>
                    updateProject("labour", e.target.value)
                  }
                />
              </label>

              <label>
                Transport Cost
                <input
                  type="number"
                  min="0"
                  step="any"
                  value={project.transport}
                  onChange={(e) =>
                    updateProject("transport", e.target.value)
                  }
                />
              </label>

              <label>
                Other Costs %
                <input
                  type="number"
                  min="0"
                  step="any"
                  value={project.other}
                  onChange={(e) =>
                    updateProject("other", e.target.value)
                  }
                />
              </label>

              <label>
                Tax / GST %
                <input
                  type="number"
                  min="0"
                  step="any"
                  value={project.tax}
                  onChange={(e) => updateProject("tax", e.target.value)}
                />
              </label>

              <label>
                Contingency %
                <input
                  type="number"
                  min="0"
                  step="any"
                  value={project.contingency}
                  onChange={(e) =>
                    updateProject("contingency", e.target.value)
                  }
                />
              </label>
            </div>

            {project.mode === "area" && (
              <p className="helper">
                Wastage is applied to material BOQ in Detailed BOQ mode.
              </p>
            )}
          </div>

          <div className="card breakdown">
            <h2>Cost Breakdown</h2>

            {project.mode === "boq" && (
              <div className="row">
                <span>Material Subtotal</span>
                <b>{money(materialSubtotal, project.currency)}</b>
              </div>
            )}

            <div className="row">
              <span>
                {project.mode === "area"
                  ? "Base Construction"
                  : "Base Materials"}
              </span>
              <b>{money(baseCost, project.currency)}</b>
            </div>

            <div className="row">
              <span>Material Wastage</span>
              <b>{money(wastage, project.currency)}</b>
            </div>

            <div className="row">
              <span>Labour</span>
              <b>{money(labourCost, project.currency)}</b>
            </div>

            <div className="row">
              <span>Transport</span>
              <b>{money(transportCost, project.currency)}</b>
            </div>

            <div className="row">
              <span>Other Costs</span>
              <b>{money(otherCost, project.currency)}</b>
            </div>

            <div className="row">
              <span>Contingency</span>
              <b>{money(contingency, project.currency)}</b>
            </div>

            <div className="row">
              <span>Tax / GST</span>
              <b>{money(tax, project.currency)}</b>
            </div>

            <div className="total">
              <span>Grand Total</span>
              <b>{money(grandTotal, project.currency)}</b>
            </div>

            {project.mode === "area" && (
              <div className="perarea">
                Approx.{" "}
                {money(
                  grandTotal /
                    Math.max(Number(project.area) || 1, 1),
                  project.currency
                )}{" "}
                / {project.areaUnit}
              </div>
            )}
          </div>
        </div>

        <div className="actions">
          <button onClick={printEstimate}>🖨 Print / Save PDF</button>
          <button className="secondary" onClick={saveEstimate}>
            {saved ? "✓ Saved" : "💾 Save Estimate"}
          </button>
        </div>
      </section>
    </main>
  );
}
